fn lobby(room:&str)->LobbyIdentity{LobbyIdentity{service_origin:"https://fixture.invalid".into(),service_id:"service".into(),principal_id:"account".into(),room_id:room.into()}}
#[test]fn lobby_delete_probes_deduplicate_all_runs_and_back_off_without_starving_other_lobbies(){
 let now=Instant::now();let a=lobby("a");let b=lobby("b");let originals=[(a.clone(),"first-run".into()),(a.clone(),"other-run".into()),(b.clone(),"other-lobby".into())].into_iter().collect::<BTreeMap<_,_>>();
 let mut cleanup=Cleanup::default();let(key,_)=cleanup.select(originals.clone(),now).unwrap();assert_eq!(key,a);assert_eq!(cleanup.probes.len(),2);cleanup.completed(a.clone(),Ok(0),now);
 assert_eq!(cleanup.select(originals.clone(),now).unwrap().0,b);cleanup.completed(b.clone(),Ok(0),now);assert!(cleanup.select(originals.clone(),now+Duration::from_secs(29)).is_none());
 assert_eq!(cleanup.select(originals.clone(),now+Duration::from_secs(30)).unwrap().0,a);
 for n in 1..=9{cleanup.completed(a.clone(),Err("NOT_FOUND or network failure".into()),now);let seconds=(5u64<<((n-1).min(6))).min(300);assert_eq!(cleanup.probes[&a].next,Some(now+Duration::from_secs(seconds)));}
 assert_eq!(cleanup.select(originals.clone(),now+Duration::from_secs(30)).unwrap().0,b,"An uncertain lobby cannot starve other lobby probes");
 cleanup.completed(a.clone(),Ok(0),now);assert_eq!(cleanup.probes[&a].failures,0);cleanup.select([(b.clone(),"kept".into())].into_iter().collect(),now);assert!(!cleanup.probes.contains_key(&a));
}
#[test]fn lobby_delete_prunes_cached_operations_permissions_and_late_worker_results(){tauri::async_runtime::block_on(async{
 use crate::g3_journal::{Journal,Original,DeletedLobby,operation_digest};
 let dir=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().nth(3).unwrap().join("spikes/noita-entry/.build").join(format!("bank-delete-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&dir).unwrap();let path=dir.join("journal.jsonl");let journal=SharedJournal::new(Journal::open(&path).unwrap());
 let make=|room:&str|Original { item:None,service_origin:"https://fixture.invalid".into(),service_id:"service".into(),service_epoch:"epoch".into(),session_epoch:"session".into(),principal_id:"account".into(),scope_json:json!({"roomId":room,"runId":"run","runEpoch":"epoch","configRevision":1,"attachmentId":"attachment","worldToken":"world"}).to_string(),operation_id:uuid::Uuid::new_v4().to_string(),direction:"withdraw".into(),amount:5};
 let old=make("deleted");let kept=make("kept");journal.begin(old.clone()).unwrap();journal.begin(kept.clone()).unwrap();let digest=operation_digest(&old).unwrap();let op=wire::Operation{operation_id:Some(old.operation_id.clone()),principal_id:Some(old.principal_id.clone()),run_id:Some("run".into()),attachment_id:Some("attachment".into()),world_token:Some("world".into()),direction:Some("withdraw".into()),amount:Some(5),delivery_id:Some(uuid::Uuid::new_v4().to_string()),payload_digest:Some(digest.clone()),state:Some("reserved".into()),..Default::default()};journal.accept_operation(&op).unwrap();
 let key=LobbyIdentity::from_original(&old).unwrap();let mut state=State{lobby:Some(key.clone()),balance:Some(100),enabled:true,fresh:true,submission:Some(json!({"id":old.operation_id})),effect:Some(json!({"id":old.operation_id,"stage":"permit"})),..Default::default()};state.operations.insert(old.operation_id.clone(),op);state.operations.insert(kept.operation_id.clone(),wire::Operation::default());state.permissions.insert(old.operation_id.clone(),Permission{permit:journal.prepare_effect(&old.operation_id).unwrap(),attempt:"a".repeat(32),digest});
 journal.retire_lobby(DeletedLobby::authenticated(key.clone()).unwrap()).unwrap();prune_state(&mut state,&journal);assert_eq!(state.operations.len(),1);assert!(state.operations.contains_key(&kept.operation_id));assert!(state.permissions.is_empty()&&state.effect.is_none()&&state.submission.is_none());
 // A worker completing after retirement cannot republish a balance/effect.
 state.effect=Some(json!({"id":old.operation_id,"stage":"permit"}));let task=tokio::spawn(async move{state});while !task.is_finished(){tokio::task::yield_now().await;}
 let mut work=Work{task:Some(task),task_lobby:Some(key),journal:Some(journal.clone()),..Default::default()};let stream=Arc::new(Mutex::new(Exchange::default()));work.tick(None,stream.clone()).await;assert_eq!(work.view()["permissions"],0);assert!(work.view()["balance"].is_null());assert!(!work.state.fresh);assert!(work.state.effect.is_none());assert_eq!(journal.pending().count(),1);
 drop(work);drop(journal);std::fs::remove_file(path).unwrap();std::fs::remove_dir(dir).unwrap();
});}

#[test]fn deletion_status_selection_covers_owned_old_lobbies_without_crossing_account_or_retired_auth(){
 let dir=std::env::temp_dir().join(format!("nt2-cleanup-selection-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&dir).unwrap();let path=dir.join("originals.jsonl");let mut journal=crate::g3_journal::Journal::open(&path).unwrap();
 for (room,principal) in [("old-lobby","account"),("current-lobby","account"),("foreign-lobby","other-account")]{journal.begin(crate::g3_journal::Original{item:None,service_origin:"https://fixture.invalid".into(),service_id:"service".into(),service_epoch:"epoch".into(),session_epoch:"session".into(),principal_id:principal.into(),scope_json:json!({"roomId":room,"runId":"run","runEpoch":"epoch","configRevision":1,"attachmentId":"attachment","worldToken":"world"}).to_string(),operation_id:uuid::Uuid::new_v4().to_string(),direction:"withdraw".into(),amount:5}).unwrap();}
 let journal=SharedJournal::new(journal);let fence=Arc::new(std::sync::atomic::AtomicU64::new(1));let owner=RecoveryOwner::new("https://fixture.invalid".into(),"service".into(),"epoch".into(),"session".into(),"account".into(),zeroize::Zeroizing::new("fixture-credential".into()),fence.clone());let selected=cleanup_originals(&owner,&journal);assert_eq!(selected.len(),2);assert!(selected.contains_key(&lobby("old-lobby"))&&selected.contains_key(&lobby("current-lobby")));assert!(!selected.contains_key(&lobby("foreign-lobby")));fence.store(2,std::sync::atomic::Ordering::Release);assert!(cleanup_originals(&owner,&journal).is_empty());assert_eq!(journal.pending().count(),3,"Selection cannot retire or mutate an original");drop(journal);std::fs::remove_file(path).unwrap();std::fs::remove_dir(dir).unwrap();
}